-- public.cellar_piece_reason(p_sub text)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.cellar_piece_reason(p_sub text)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  select case
    when d.id is null then null
    when coalesce(d.hearth, false) then 'No open fires in a cellar.'
    when coalesce(d.cart, false) or exists (select 1 from vehicle_def v where v.id = d.id)
         or exists (select 1 from boat_def b where b.id = d.id)
      then 'No carts, vehicles or boats in a cellar.'
    when cellar_outdoor(d.id)
      then upper(left(lower(d.name), 1)) || substr(lower(d.name), 2)
           || ': not in a cellar.'
    end
  from (select 1) one left join furniture_def d on d.id = p_sub
$function$
